import json

from .pricing import total
from .store import OrderStore

STORE = OrderStore()


def list_orders(query: dict[str, str]) -> str:
    return json.dumps([{"id": o.id, "customer": o.customer, "total": total(o)} for o in STORE.all()])


def get_order(order_id: int) -> str:
    o = STORE.get(order_id)
    return json.dumps({"error": "not found"}) if o is None else json.dumps({"id": o.id, "total": total(o)})
